// The kinds of the invoices generated by the service (domain §22.12).
var (
	kindOneOff         = kernel.InvoiceKind{Type: invoice.TypeOneOff}
	kindAdvanceCharges = kernel.InvoiceKind{Type: invoice.TypeAdvanceCharges}
	kindInAdvance      = kernel.InvoiceKind{Type: invoice.TypeSubscription, UsesBillingDate: true}
	kindProgressive    = kernel.InvoiceKind{Type: invoice.TypeProgressiveBilling, UsesGracePeriod: true}
)

// subscriptionKind returns the kind of a subscription invoice; periodic
// invoices are recurring.
func subscriptionKind(recurring bool) kernel.InvoiceKind {
	return kernel.InvoiceKind{Type: invoice.TypeSubscription, Recurring: recurring, UsesGracePeriod: true}
}

// kindOf returns the kind of a stored invoice from its type and its
// invoice subscriptions.
func kindOf(inv *invoice.Invoice, iss []*invoice.Subscription) kernel.InvoiceKind {
	switch inv.Type {
	case invoice.TypeSubscription:
		recurring := len(iss) > 0
		for _, is := range iss {
			if is.Reason == invoice.InvoicingReasonInAdvanceCharge {
				return kindInAdvance
			}
			recurring = recurring && is.Recurring
		}
		return subscriptionKind(recurring)
	case invoice.TypeProgressiveBilling:
		return kindProgressive
	case invoice.TypeAdvanceCharges:
		return kindAdvanceCharges
	default:
		return kernel.InvoiceKind{Type: inv.Type}
	}
}

// settleOptions tune [Service.settle].
type settleOptions struct {
	// draft applies only progressive billing credits (domain §22.8).
	draft bool
	// preview computes without writing.
	preview bool
	// aggregate sums the fees' own taxes and applies no deduction
	// (advance charges invoices, lago AggregateAmountsAndTaxesFromFees).
	aggregate bool
	// plans are the plans of subscriptions that are not stored (previews).
	plans map[core.SubscriptionID]*catalog.Plan
	// resolver resolves the fees' taxes; nil builds one.
	resolver *kernel.TaxResolver
}

// settled is the outcome of [Service.settle].
type settled struct {
	// appliedTaxes are the invoice's applied taxes.
	appliedTaxes []*invoice.AppliedTax
	// before are the deductions before taxes.
	before deduct.BeforeTaxes
	// taxFailure is the tax provider's error; the invoice then fails.
	taxFailure error
	// pending is true while the provider computes the taxes.
	pending bool
	// gated is true when a pending payment rule of a billed subscription
	// holds the invoice open (domain §9.3).
	gated bool
}

// settle applies the deductions and the taxes of inv, whose fees are fees,
// in the order of domain §22.7, and stores the fees, the applied taxes and
// a tax error detail (not the invoice). A provider failure is not an
// error: it is reported in the outcome with the tax status.
func (s *Service) settle(ctx context.Context, r port.Repos, env *kernel.CustomerEnv, inv *invoice.Invoice, fees []*invoice.Fee, o settleOptions) (settled, error) {
	dopts := deduct.Options{Draft: o.draft, Preview: o.preview, Plans: o.plans}
	var before deduct.BeforeTaxes
	if !o.aggregate {
		var err error
		if before, err = s.deduct.ApplyBeforeTaxes(ctx, r, env, inv, fees, dopts); err != nil {
			return settled{}, err
		}
	}
	out := settled{before: before}
	resolver := o.resolver
	if resolver == nil {
		resolver = kernel.NewTaxResolver(r, env)
	}
	ded := invoice.Deductions{ProgressiveBillingCredit: before.ProgressiveBillingCredit, Coupons: before.Coupons}
	res, err := resolver.Compute(ctx, s.d, kernel.TaxInput{Invoice: inv, Fees: fees, Deductions: ded, AggregateFeeTaxes: o.aggregate, Draft: o.draft, Inline: o.preview})
	switch {
	case err == nil:
		inv.ApplyTotals(res.Totals)
		inv.TaxesRate = res.TaxesRate
		inv.TaxStatus = invoice.TaxStatusSucceeded
		out.appliedTaxes = res.AppliedTaxes
	case errors.Is(err, kernel.ErrTaxesPending):
		out.pending = true
		inv.TaxStatus = invoice.TaxStatusPending
		applyUntaxed(inv, fees, ded)
	case errors.Is(err, kernel.ErrTaxProvider):
		out.taxFailure = err
		inv.TaxStatus = invoice.TaxStatusFailed
		applyUntaxed(inv, fees, ded)
	default:
		return settled{}, err
	}
	if out.appliedTaxes == nil {
		out.appliedTaxes = []*invoice.AppliedTax{}
	}
	if inv.TaxStatus == invoice.TaxStatusSucceeded && !o.aggregate {
		// The progressive credit notes exist before the credit notes are
		// applied, so the invoice consumes them (lago
		// Credits::ProgressiveBillingService before CreditNoteService).
		if !o.draft && !o.preview {
			if err := s.creditProgressive(ctx, r, inv.OrganizationID, before.ProgressiveCreditNotes); err != nil {
				return settled{}, err
			}
		}
		if _, err := s.deduct.ApplyAfterTaxes(ctx, r, env, inv, fees, out.appliedTaxes, dopts); err != nil {
			return settled{}, err
		}
	}
	if inv.TotalAmount == 0 {
		inv.PaymentStatus = core.PaymentStatusSucceeded
	} else {
		inv.PaymentStatus = core.PaymentStatusPending
	}
	inv.UpdatedAt = s.d.Now()
	if o.preview {
		return out, nil
	}
	for _, f := range fees {
		f.UpdatedAt = s.d.Now()
		if err := r.Fees.Update(ctx, f); err != nil {
			return settled{}, fmt.Errorf("save fee %s: %w", f.ID, err)
		}
	}
	if err := r.InvoiceAppliedTaxes.ReplaceForInvoice(ctx, inv.OrganizationID, inv.ID, out.appliedTaxes); err != nil {
		return settled{}, fmt.Errorf("save taxes of invoice %s: %w", inv.ID, err)
	}
	if err := r.ErrorDetails.DeleteByInvoice(ctx, inv.OrganizationID, inv.ID, invoice.ErrorCodeTaxError); err != nil {
		return settled{}, fmt.Errorf("clear tax errors of invoice %s: %w", inv.ID, err)
	}
	if out.taxFailure != nil {
		if err := s.saveError(ctx, r, inv, invoice.ErrorCodeTaxError, out.taxFailure); err != nil {
			return settled{}, err
		}
	}
	return out, nil
}

// applyUntaxed sets the totals of inv without taxes, while its taxes are
// pending or failed.
func applyUntaxed(inv *invoice.Invoice, fees []*invoice.Fee, ded invoice.Deductions) {
	amounts := make([]int64, len(fees))
	for i, f := range fees {
		amounts[i] = f.Amount
	}
	inv.ApplyTotals(invoice.ComputeTotals(amounts, ded))
	inv.TaxesRate = money.Zero
}

// saveError stores an error detail of inv with code.
func (s *Service) saveError(ctx context.Context, r port.Repos, inv *invoice.Invoice, code invoice.ErrorCode, cause error) error {
	details, err := json.Marshal(map[string]string{"error": cause.Error()})
	if err != nil {
		return fmt.Errorf("encode error detail: %w", err)
	}
	e := &invoice.ErrorDetail{
		ID: core.NewID[core.ErrorDetailID](s.d.IDs), OrganizationID: inv.OrganizationID, InvoiceID: inv.ID,
		Code: code, Details: details, CreatedAt: s.d.Now(),
	}
	if err := r.ErrorDetails.Create(ctx, e); err != nil {
		return fmt.Errorf("save error detail of invoice %s: %w", inv.ID, err)
	}
	return nil
}

// conclude moves inv to the status it leaves generating (or draft, when
// finalizing) with (domain §22.12), numbers it when finalized and saves
// it. A tax failure fails a generating or open invoice; a draft keeps its
// status.
func (s *Service) conclude(ctx context.Context, r port.Repos, env *kernel.CustomerEnv, inv *invoice.Invoice, k kernel.InvoiceKind, st settled, finalizing bool) error {
	now := s.d.Now()
	kk := k
	if finalizing {
		kk.UsesGracePeriod = false
	}
	var err error
	switch status := kernel.FinalStatus(inv, env, kk, st.gated); {
	case st.taxFailure != nil:
		// A failed tax pull fails the invoice unless it is a draft (lago
		// Invoices::ProviderTaxes::PullTaxesAndApplyService,
		// app/services/invoices/provider_taxes/pull_taxes_and_apply_service.rb:29).
		switch inv.Status {
		case invoice.StatusGenerating:
			to := invoice.StatusFailed
			if status == invoice.StatusDraft {
				to = invoice.StatusDraft
			}
			err = inv.Transition(to, now)
		case invoice.StatusOpen:
			err = inv.Transition(invoice.StatusFailed, now)
		}
	case inv.Status != invoice.StatusGenerating && st.pending:
		// A draft or failed invoice waits for its taxes in its status;
		// pulling them finalizes it.
	case status == invoice.StatusFinalized,
		inv.Status != invoice.StatusGenerating && status == invoice.StatusClosed:
		// libs/core moves a draft, open or failed invoice only to
		// finalized, so a zero-amount one is finalized instead of closed.
		err = kernel.Finalize(ctx, r, env, inv, k, now)
	case inv.Status != status:
		err = inv.Transition(status, now)
	}
	if err != nil {
		return fmt.Errorf("conclude invoice %s: %w", inv.ID, err)
	}
	inv.UpdatedAt = now
	if err := r.Invoices.Update(ctx, inv); err != nil {
		return fmt.Errorf("save invoice %s: %w", inv.ID, err)
	}
	return nil
}

// announce emits the webhooks and enqueues the jobs of an invoice that
// was just generated or finalized (lago SendWebhookJob, GenerateDocumentsJob,
// Invoices::Payments::CreateService): invoice.drafted for a new draft,
// the created event, the document and the payment (unless self-billed)
// for a finalized invoice, the provider taxes retry for an invoice waiting for its taxes.
func (s *Service) announce(ctx context.Context, r port.Repos, inv *invoice.Invoice, created webhook.EventType, drafted bool) error {
	org := inv.OrganizationID
	now := s.d.Now()
	switch {
	case inv.TaxStatus == invoice.TaxStatusPending:
		return kernel.Enqueue(ctx, r, org, kernel.JobPullProviderTaxes, kernel.InvoiceArgs{InvoiceID: inv.ID}, "invoice:"+inv.ID.String(), now.Add(pullTaxesDelay))
	case inv.Status == invoice.StatusDraft:
		if !drafted {
			return nil
		}
		return kernel.Emit(ctx, s.d, org, webhook.EventTypeInvoiceDrafted, "invoice", kernel.ObjectID(inv.ID), inv)
	case inv.Status != invoice.StatusFinalized:
		return nil
	}
	if err := kernel.Emit(ctx, s.d, org, created, "invoice", kernel.ObjectID(inv.ID), inv); err != nil {
		return err
	}
	args := kernel.InvoiceArgs{InvoiceID: inv.ID}
	if err := kernel.Enqueue(ctx, r, org, kernel.JobGenerateInvoiceDocument, args, "invoice:"+inv.ID.String(), now); err != nil {
		return err
	}
	// A self-billed invoice is paid by the organization to its partner,
	// never collected (lago Invoices::Payments::CreateService).
	if inv.TotalAmount > 0 && inv.PaymentStatus != core.PaymentStatusSucceeded && !inv.SelfBilled {
		return kernel.Enqueue(ctx, r, org, kernel.JobCreateInvoicePayment, args, "invoice:"+inv.ID.String(), now)
	}
	return nil
}

// emitFees emits fee.created for fees attached to no invoice.
func (s *Service) emitFees(ctx context.Context, fees []*invoice.Fee) error {
	for _, f := range fees {
		if err := kernel.Emit(ctx, s.d, f.OrganizationID, webhook.EventTypeFeeCreated, "fee", kernel.ObjectID(f.ID), f); err != nil {
			return err
		}
	}
	return nil
}

// creditProgressive issues the credit notes giving back, on progressive
// billing invoices, what a finalized invoice could not deduct (lago
// CreditNotes::CreateFromProgressiveBillingInvoice).
func (s *Service) creditProgressive(ctx context.Context, r port.Repos, org core.OrganizationID, notes []deduct.ProgressiveCreditNote) error {
	for _, n := range notes {
		items := make([]creditnotes.ItemInput, len(n.Items))
		for i, it := range n.Items {
			items[i] = creditnotes.ItemInput{FeeID: it.FeeID, Amount: money.NewFromInt(it.Amount)}
		}
		in := creditnotes.ProgressiveInput{OrganizationID: org, InvoiceID: n.InvoiceID, Amount: money.NewFromInt(n.Amount), Items: items}
		if _, err := s.creditNotes.CreateFromProgressiveBillingInvoice(ctx, r, in); err != nil {
			return fmt.Errorf("credit progressive billing invoice %s: %w", n.InvoiceID, err)
		}
	}
	return nil
}

// flagLifetimeUsage asks for the lifetime usage of the subscriptions to
// be recomputed after their invoices changed (lago
// LifetimeUsages::FlagRefreshFromInvoiceService).
func (s *Service) flagLifetimeUsage(ctx context.Context, r port.Repos, org core.OrganizationID, subs []core.SubscriptionID) error {
	for _, id := range subs {
		lu, err := r.LifetimeUsages.GetBySubscription(ctx, org, id)
		switch {
		case err == nil:
			lu.FlagForRecalculation(s.d.Now())
			if err := r.LifetimeUsages.Upsert(ctx, lu); err != nil {
				return fmt.Errorf("flag lifetime usage of %s: %w", id, err)
			}
		case !errors.Is(err, core.ErrNotFound):
			return fmt.Errorf("load lifetime usage of %s: %w", id, err)
		}
		args := kernel.SubscriptionArgs{SubscriptionID: id}
		if err := kernel.Enqueue(ctx, r, org, kernel.JobRefreshLifetimeUsage, args, "subscription:"+id.String(), s.d.Now()); err != nil {
			return err
		}
	}
	return nil
}
